formulas.rawText:
{
  "originalFormula": "J_n = 1.6 \\times 10^{-19} \\times (-10^{14}) \\times 34.48 \\times (-0.55 \, \\text{mA/cm}^2)",
  "genericFormula": "J_n = q \\times N \\times A \\times I",
  "description": "Esta fórmula representa a densidade de corrente de portadores negativos (elétrons) em um semicondutor. A densidade de corrente é uma medida de quão intensa é a corrente elétrica que flui por unidade de área, considerando a contribuição de elétrons que se movem sob a influência de um campo elétrico.",
  "concepts": [
    "Densidade de corrente",
    "Portadores de carga",
    "Semicondutores",
    "Campo elétrico"
  ],
  "symbols": [
    {
      "symbol": "J_n",
      "description": "Representa a densidade de corrente dos portadores negativos, que é a quantidade de corrente elétrica por unidade de área, especificamente para elétrons em um semicondutor."
    },
    {
      "symbol": "q",
      "description": "Representa a carga elementar, que é a carga de um único elétron, uma constante fundamental na física."
    },
    {
      "symbol": "N",
      "description": "Representa a concentração de portadores de carga, ou seja, o número de elétrons disponíveis por unidade de volume no semicondutor."
    },
    {
      "symbol": "A",
      "description": "Representa a área através da qual a corrente está fluindo, geralmente medida em centímetros quadrados."
    },
    {
      "symbol": "I",
      "description": "Representa a corrente elétrica, que é o fluxo de carga elétrica, medida em miliamperes por centímetro quadrado neste contexto."
    }
  ]
}

standaloneFormulas.rawText:
{
  "originalFormula": "p_0 = 10^{15} \, \\text{cm}^{-3}, n_0 = 1 \\times 10^{5} \, \\text{cm}^{-3}",
  "genericFormula": "p_0 = P \, \\text{cm}^{-3}, n_0 = N \, \\text{cm}^{-3}",
  "description": "Esta fórmula representa as concentrações de portadores de carga em um semicondutor. O primeiro termo, p_0, é a concentração de lacunas (portadores positivos) e o segundo termo, n_0, é a concentração de elétrons (portadores negativos). Essas concentrações são fundamentais para entender o comportamento elétrico do material semicondutor.",
  "concepts": [
    "Semicondutores",
    "Portadores de carga",
    "Concentração de lacunas",
    "Concentração de elétrons"
  ],
  "symbols": [
    {
      "symbol": "p_0",
      "description": "Representa a concentração de lacunas em um semicondutor, que são os locais onde um elétron poderia estar, mas não está presente, agindo como portadores de carga positiva."
    },
    {
      "symbol": "n_0",
      "description": "Representa a concentração de elétrons em um semicondutor, que são os portadores de carga negativa responsáveis pela condução elétrica."
    },
    {
      "symbol": "P",
      "description": "É uma variável genérica que representa a concentração de lacunas em um semicondutor, em unidades de número por centímetro cúbico."
    },
    {
      "symbol": "N",
      "description": "É uma variável genérica que representa a concentração de elétrons em um semicondutor, também em unidades de número por centímetro cúbico."
    }
  ]
}
